async function joinB(p,platform){await p.locator('#workspace-shell button').filter({hasText:'Join a workspace'}).click();await p.locator('.workspace-join input[placeholder="e.g. Acme"]').fill('Personal B');const raw=fs.readFileSync(path.join(world,'invite-b-'+platform),'utf8').trim().split('#')[1];await p.locator('.workspace-join textarea').fill(decodeURIComponent(raw));await p.locator('.workspace-join input[placeholder="laptop"]').fill(platform==='browser'?'tablet':'laptop');await p.locator('.workspace-join .btn.primary').click();await p.waitForFunction(()=>window.agentnet.workspaces.list().length===2);const id=await p.evaluate(()=>window.agentnet.workspaces.list().find(w=>w.id!=='default').id);await select(p,id);await api(p,'/api/person',{label:'Alice'});return id;}
async function setupDM(p,r){const dm=await api(p,'/api/dm/new',{address:'bob/desk'});await api(p,'/api/dm/send',{conv:dm.id,body:'History '+r});await p.evaluate(id=>openDM(id),dm.id);await ready(p);return dm.id;}
(async()=>{
fs.mkdirSync(evidence,{recursive:true,mode:0o700});const env={...process.env,HOME:path.join(world,'browser-home')};fs.mkdirSync(env.HOME,{recursive:true});for(const [k,d]of Object.entries({XDG_CONFIG_HOME:'config',XDG_CACHE_HOME:'cache',XDG_DATA_HOME:'data'})){env[k]=path.join(env.HOME,d);fs.mkdirSync(env[k]);}
browser=await chromium.launch({headless:true,executablePath:process.env.AGENTNET_CHROMIUM,env,args:['--ignore-certificate-errors-spki-list='+spki,'--disable-background-networking','--host-resolver-rules=MAP * ~NOTFOUND, EXCLUDE 127.0.0.1']});
const contexts=await Promise.all([0,1,2,3].map(()=>browser.newContext({viewport:{width:1280,height:900}})));for(const context of contexts)await context.route('**/*',r=>{const o=new URL(r.request().url()).origin;if(allowed.has(o))return r.continue();result.external.push(o);return r.abort();});
const [daemon,engine,peerA,peerB]=await Promise.all(contexts.map(c=>c.newPage()));
for(const p of [daemon,engine,peerA,peerB]){p.setDefaultTimeout(15000);p.on('pageerror',e=>result.errors.push(e.message));p.on('response',r=>{const name=new URL(r.url()).pathname.split('/').pop();if(expected[name])reads.push(r.body().then(bytes=>{assert.equal(digest(bytes),expected[name],name+' frozen bytes');result.assets[name]=digest(bytes);}).catch(e=>result.errors.push(e.message)));});}
await daemon.goto(ui('alice-a'));await ready(daemon);stage='daemon B join';const daemonB=await joinB(daemon,'daemon');
const raw=fs.readFileSync(path.join(world,'link-a'),'utf8').match(/agentnet-link-v2:[A-Za-z0-9_-]+/)[0];const offer=JSON.parse(Buffer.from(raw.split(':')[1],'base64url')),inv=JSON.parse(Buffer.from(offer.invite.split(':')[1],'base64url'));delete inv.cert;offer.invite='agentnet-invite-v1:'+Buffer.from(JSON.stringify(inv)).toString('base64url');
await engine.goto(origin('a')+'/#agentnet-link-v2:'+Buffer.from(JSON.stringify(offer)).toString('base64url'));await engine.locator('#join-name').fill('tablet');await engine.locator('button.join-go').click();let link;await until(()=>{link=cli('alice-a','person','links').match(/^([a-f0-9]{32})\s+pending\s+[^\n]*tablet/m)?.[1];return!!link;});cli('alice-a','person','approve',link);await ready(engine);stage='browser B join';const engineB=await joinB(engine,'browser');
await peerA.goto(ui('bob-a'));await ready(peerA);await peerB.goto(ui('bob-b'));await ready(peerB);
const cases=[];
for(const [platform,p,idB]of [['daemon',daemon,daemonB],['browser',engine,engineB]]){
 stage=platform+' scope';await select(p,'default');const identityA=await api(p,'/api/overview');const convA=await setupDM(p,platform+' A');await select(p,idB);const identityB=await api(p,'/api/overview');assert.equal(identityA.me.address,identityB.me.address);assert.notEqual(identityA.me.fingerprint,identityB.me.fingerprint);assert.notEqual(identityA.person.person,identityB.person.person);const convB=await setupDM(p,platform+' B');assert.notEqual(convA,convB);cases.push({platform,p,idB,convA,convB});
 for(const width of [390,1280]){
  stage=platform+' drafts '+width;await p.setViewportSize({width,height:900});await select(p,'default');await p.locator('#timeline').getByRole('button',{name:'Reply',exact:true}).last().click();await p.locator('#body').fill(platform+' draft A '+width);await p.locator('#file-input').setInputFiles({name:'A-'+width+'.txt',mimeType:'text/plain',buffer:Buffer.from('BYTES A '+platform+' '+width)});const replyA=await p.evaluate(()=>state.dmReply.id);await capture(p,platform+'-A-draft',width);
  await select(p,idB);assert.equal(await p.locator('#body').inputValue(),'');assert.equal(await p.evaluate(()=>state.files.length),0);await p.locator('#timeline').getByRole('button',{name:'Reply',exact:true}).last().click();await p.locator('#body').fill(platform+' draft B '+width);await p.locator('#file-input').setInputFiles({name:'B-'+width+'.txt',mimeType:'text/plain',buffer:Buffer.from('BYTES B '+platform+' '+width)});const replyB=await p.evaluate(()=>state.dmReply.id);await capture(p,platform+'-B-draft',width);
  await select(p,'default');assert.equal(await p.locator('#body').inputValue(),platform+' draft A '+width);assert.equal(await p.evaluate(()=>state.dmReply.id),replyA);assert.deepEqual(await p.evaluate(()=>state.files.map(f=>f.name)),['A-'+width+'.txt']);
  if(platform==='daemon'&&width===1280){let upload;const uploadURL=new URL(ui('alice-a')).origin+'/workspaces/default/*/api/upload?*';let release;const started=new Promise(r=>release=r);await p.context().route(uploadURL,r=>{upload=r;release();});await p.locator('#send').click();await started;await select(p,idB);await upload.continue();await p.context().unroute(uploadURL);await until(async()=>!(await p.evaluate(()=>state.sending)));assert.equal(await p.locator('#body').inputValue(),platform+' draft B '+width);await select(p,'default');result.checks.push('captured daemon A upload completed while B selected; A send stayed A and B draft untouched');}else await p.locator('#send').click();await until(async()=>!(await p.evaluate(()=>state.sending)));await until(async()=>{const view=await api(peerA,'/api/dm?id='+convA);return view.messages.some(m=>m.body===platform+' draft A '+width);});const foundA=(await api(peerA,'/api/dm?id='+convA)).messages.find(m=>m.body===platform+' draft A '+width);assert.equal(foundA.reply_to,replyA);const bytesA=await peerA.evaluate(async m=>Array.from((await window.agentnet.file(m.id,0,m.dir)).bytes),foundA);assert.equal(Buffer.from(bytesA).toString(),'BYTES A '+platform+' '+width);
  await select(p,idB);assert.equal(await p.locator('#body').inputValue(),platform+' draft B '+width);assert.equal(await p.evaluate(()=>state.dmReply.id),replyB);assert.deepEqual(await p.evaluate(()=>state.files.map(f=>f.name)),['B-'+width+'.txt']);await p.locator('#send').click();await until(async()=>!(await p.evaluate(()=>state.sending)));await until(async()=>(await api(peerB,'/api/dm?id='+convB)).messages.some(m=>m.body===platform+' draft B '+width));const foundB=(await api(peerB,'/api/dm?id='+convB)).messages.find(m=>m.body===platform+' draft B '+width);const bytesB=await peerB.evaluate(async m=>Array.from((await window.agentnet.file(m.id,0,m.dir)).bytes),foundB);assert.equal(Buffer.from(bytesB).toString(),'BYTES B '+platform+' '+width);await capture(p,platform+'-B-sent',width);
  result.checks.push(platform+' '+width+' same address/different keys/history; A/B/A text/reply/files; scoped sends/bytes');
 }
}
// A selected provider failure must clear foreign content both while pending
// and after rejection. Inject failure only in this read-only UI operation.
for(const c of cases){
 stage=c.platform+' selected view load failure';await select(c.p,'default');
 let failedRoute,trigger;const pending=new Promise(r=>trigger=r);let pattern;
 if(c.platform==='daemon'){
  pattern=new URL(ui('alice-a')).origin+'/workspaces/'+c.idB+'/*/api/overview';
  await c.p.context().route(pattern,r=>{failedRoute=r;trigger();});
 }else{
  await c.p.evaluate(id=>{const e=window.agentnetWorkspaces.shell.members.get(id).engine,original=e.api;e.api=function(p,b){if(p==='/api/overview'){e.api=original;window.__workspaceOverviewPending=true;return new Promise((_,reject)=>{window.__workspaceOverviewFail=()=>reject(Error('Synthetic selected overview unavailable'));});}return original.call(this,p,b);};},c.idB);
 }
 await c.p.locator('#workspace-shell select').selectOption(c.idB);
 if(c.platform==='daemon')await pending;else await c.p.waitForFunction(()=>window.__workspaceOverviewPending);
 await assertScope(c.p,'selected load pending');await capture(c.p,c.platform+'-B-load-pending',1280);
 if(c.platform==='daemon'){await failedRoute.fulfill({status:503,body:'Synthetic selected overview unavailable'});await c.p.context().unroute(pattern);}else await c.p.evaluate(()=>{window.__workspaceOverviewFail();delete window.__workspaceOverviewPending;delete window.__workspaceOverviewFail;});
 await c.p.evaluate(()=>state.switching);await assertScope(c.p,'selected load rejected');assert.equal(await c.p.locator('#lost').isVisible(),true);await capture(c.p,c.platform+'-B-load-failed',1280);await select(c.p,'default');await select(c.p,c.idB);result.checks.push(c.platform+' selected overview pending/failure clears foreign DOM; restored view remains scoped');
}
stage='B stopped reload A';process.kill(Number(fs.readFileSync(path.join(world,'hub-b-pid'),'utf8')),'SIGTERM');for(const c of cases){await select(c.p,'default');await c.p.reload();await ready(c.p);assert.equal(await c.p.evaluate(()=>window.agentnet.workspaces.list().length),2);await select(c.p,c.idB);await capture(c.p,c.platform+'-B-offline',1280);const visible=await c.p.locator('#timeline:visible').allTextContents();const snapshot=await c.p.evaluate(()=>({workspace:window.agentnet.workspace.id,dm:state.dm,thread:state.thread,data:state.data?.id,dmData:state.dmData?.id,visibleTimeline:document.querySelector('#timeline').innerText}));result.offlineSnapshots=result.offlineSnapshots||[];result.offlineSnapshots.push({platform:c.platform,...snapshot});assert(!visible.some(t=>/History (?:daemon|browser) A|(?:daemon|browser) draft A|A while B offline/.test(t)),c.platform+' selected B displays A history after reload');await select(c.p,'default');await c.p.evaluate(id=>openDM(id),c.convA);await c.p.locator('#body').fill(c.platform+' A while B offline');await c.p.locator('#send').click();await until(async()=>(await api(peerA,'/api/dm?id='+c.convA)).messages.some(m=>m.body===c.platform+' A while B offline'));result.checks.push(c.platform+' reload retained offline B; A still sends');}
stage='B reconnect';const back=fs.readFileSync(path.join(world,'backend-b'),'utf8').trim();restarted=spawn(binary,['hub','serve','--data',path.join(world,'hub-b'),'--listen','127.0.0.1:'+back,'--platform-tls','--web','--public-url',origin('b'),'--browser-origin',origin('a')],{env:process.env,stdio:['ignore',fs.openSync(path.join(world,'hub-b-restart.log'),'a'),fs.openSync(path.join(world,'hub-b-restart.log'),'a')]});
for(const c of cases){await select(c.p,c.idB);await c.p.reload();await ready(c.p);await select(c.p,c.idB);await c.p.evaluate(id=>openDM(id),c.convB);await c.p.locator('#body').fill(c.platform+' B reconnected');await c.p.locator('#send').click();await until(async()=>(await api(peerB,'/api/dm?id='+c.convB)).messages.some(m=>m.body===c.platform+' B reconnected'));await capture(c.p,c.platform+'-B-reconnected',1280);result.checks.push(c.platform+' B reconnect uses retained membership/history');}
await Promise.all(reads);assert.deepEqual(result.errors,[]);assert.deepEqual(result.external,[]);result.pass=true;
})().catch(async e=>{result.stage=stage;result.failure=e.stack;console.error(stage+': '+e.message);if(browser)for(const c of browser.contexts())for(const [i,p]of c.pages().entries()){fs.writeFileSync(path.join(evidence,'failure-'+i+'.txt'),await p.locator('body').innerText().catch(()=>''));await p.screenshot({path:path.join(evidence,'failure-'+i+'.png')}).catch(()=>{});}process.exitCode=1;}).finally(async()=>{if(browser)await browser.close();if(restarted){restarted.kill();await new Promise(r=>restarted.once('exit',r));}fs.writeFileSync(path.join(evidence,'result.json'),JSON.stringify(result,null,2));console.log(JSON.stringify({pass:result.pass,checks:result.checks,stage:result.stage}));});
